	(108858, 9226991, 'tatoeba', '事前にお知らせいたします。', 'I\'ll let you know in advance.'),
	(108859, 13011278, 'tatoeba', '解雇された。', 'We got fired.'),
	(108860, 13681880, 'tatoeba', '解雇します。', 'I\'ll fire him.'),
