	(122715, 11256138, 'tatoeba', '愛を基盤に生きている。', 'Love is the bedrock of my life.'),
	(122716, 122897, 'tatoeba', '日記が彼女が後に書いた本の基盤となった。', 'Her diaries formed the basis of the book she later wrote.'),
	(122717, 122899, 'tatoeba', '日陰にいなさい。', 'Keep in the shade.'),
	(122718, 154748, 'tatoeba', '私は日陰に立っている。', 'I\'m standing in the shade.'),
	(122719, 138074, 'tatoeba', '太陽は明るく照っている。', 'The sun is shining brightly.'),
	(122720, 173272, 'tatoeba', '降ろうが照ろうが、私は行く。', 'I will go, rain or shine.'),
